def subterms(x):
    out=[]
    stack=[x]
    while stack:
        y=stack.pop()
        if isinstance(y,list) and y:
            out.append(y)
            i=1
            while i<len(y):
                if isinstance(y[i],list):
                    stack.append(y[i])
                i+=1
    return out

def has_tag(x,name):
    for y in subterms(x):
        if y[0]==name:
            return True
    return False

def participant_tags(x,defs):
    tags=set()
    stack=[x]
    expanded=set()
    while stack:
        y=stack.pop()
        if not isinstance(y,list) or not y:
            continue
        n=y[0]
        tags.add(n)
        if n=='representatives_of' and len(y)>1:
            k=str(y[1])
            if k not in expanded:
                expanded.add(k)
                for d in defs:
                    if str(d[0])==k:
                        stack.append(d[1])
            continue
        i=1
        while i<len(y):
            if isinstance(y[i],list):
                stack.append(y[i])
            i+=1
    return tags

def unresolved_representative(x,defs):
    for y in subterms(x):
        if y[0]=='representatives_of' and len(y)>1:
            k=str(y[1])
            found=False
            for d in defs:
                if str(d[0])==k:
                    found=True
            if not found:
                return True
    return False

def unique(xs):
    out=[]
    for x in xs:
        if x not in out:
            out.append(x)
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for n in nodes:
        byid[n.get('id')]=n
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for t in subterms(node.get('term')):
                entries.append((t,root))
            for c in node.get('child_ids',[]):
                if c not in seen:
                    todo.append(c)
    defs=[]
    def_roots=[]
    for t,r in entries:
        if t[0]=='define_representative' and len(t)>=3:
            defs.append((t[1],t[2]))
            def_roots.append(r)
    perms=[]
    prohibs=[]
    relevant=[]
    for t,r in entries:
        if t[0] not in ('permission','prohibition') or len(t)<3:
            continue
        a=t[2]
        if not isinstance(a,list) or len(a)<3 or a[0]!='disclose':
            continue
        if not has_tag(a[1],'confidential_information'):
            continue
        relevant.append(r)
        tags=participant_tags(a[2],defs)
        if t[0]=='permission':
            perms.append((r,tags,t,a[2]))
        else:
            prohibs.append((r,tags,t,a[2]))
    relevant=unique(relevant)
    if not relevant:
        return {'handled':False,'answer':None,'used_nodes':[]}
    employee={'employees_of'}
    external={'third_parties','consultants_of','agents_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','independent_contractors_of'}
    wanted=employee if task=='nda-5' else external
    for r,tags,t,recipient in perms:
        if tags.intersection(wanted):
            used=[r]
            if has_tag(recipient,'representatives_of'):
                used+=def_roots
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    if task=='nda-5':
        for r,tags,t,recipient in prohibs:
            if 'employees_of' in tags:
                return {'handled':True,'answer':'Contradiction','used_nodes':[r]}
        return {'handled':True,'answer':'NotMentioned','used_nodes':relevant}
    for r,tags,t,recipient in prohibs:
        if 'third_parties' not in tags or 'outsiders_to' in tags:
            continue
        if has_tag(t,'cross_reference_exception'):
            continue
        if unresolved_representative(t,defs):
            continue
        return {'handled':True,'answer':'Contradiction','used_nodes':[r]}
    return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+def_roots)}
